  String getStringFrDuration(String i) {
    if (i == '') {
      return '';
    }
    if (int.parse(i) > 1) {
      return '$i days';
    }
    return '$i day';
  }

  void startTimer() {
    const oneSec = Duration(seconds: 1);
    _timer = Timer.periodic(oneSec, (Timer timer) {
      if (_start == 0) {
        timer.cancel();
      } else {
        _start--;
      }
      notifyListeners();
    });
  }

