                              Divider(color: AppColors.infoGrey1),
                              SizedBox(height: 6.10.h),
                              Row(
                                mainAxisAlignment:
                                    MainAxisAlignment.spaceBetween,
                                children: [
                                  TextView(
                                    text: 'Total',
                                    textStyle: TextStyle(
                                      fontFamily: 'GoogleSans',
                                      fontSize: 16.80.sp,
                                      color: AppColors.black,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  TextView(
                                    text: '₦$costTotal.00',
                                    textStyle: TextStyle(
                                      fontFamily: 'Arial',
                                      fontSize: 16.80.sp,
                                      color: AppColors.black,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ],
                )
              : SizedBox.shrink(),
          SizedBox(height: 16.20.h),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              IconButton(
                onPressed:
                    model.medicationClassList[indexOfMedicationClassList] ==
                        model.medicationClassList.first
                    ? () {}
                    : () {
                        indexOfMedicationClassList -= 1;
                        model.notifyListeners();
                      },
                icon: Icon(
                  Icons.arrow_back,
                  size: 22.sp,
                  color:
                      model.medicationClassList[indexOfMedicationClassList] ==
                          model.medicationClassList.first
                      ? AppColors.primaryLight.withOpacity(.7)
                      : AppColors.primary,
                ),
              ),
              SizedBox(width: 10.h),
              TextView(
                text:
                    '${indexOfMedicationClassList + 1}/${model.medicationClassList.length}',
                textStyle: TextStyle(
                  fontFamily: 'Arial',
                  fontSize: 13.2.sp,
                  fontWeight: FontWeight.w400,
                  color: AppColors.infoGrey,
                ),
              ),
              SizedBox(width: 10.h),
              IconButton(
                onPressed:
                    model.medicationClassList[indexOfMedicationClassList] ==
                        model.medicationClassList.last
                    ? () {}
                    : () {
                        indexOfMedicationClassList += 1;
                        model.notifyListeners();
                      },
                icon: Icon(
                  Icons.arrow_forward,
                  size: 22.sp,
                  color:
                      model.medicationClassList[indexOfMedicationClassList] ==
                          model.medicationClassList.last
                      ? AppColors.primaryLight.withOpacity(.7)
                      : AppColors.primary1,
                ),
              ),
            ],
          ),
          SizedBox(height: 26.h),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Flexible(
                child: ButtonWidget(
                  border: 100.r,
                  buttonColor: AppColors.dashboard,
                  buttonText: 'Previous',
                  color: AppColors.deep,
                  fontSize: 14.sp,
                  buttonBorderColor: AppColors.transparent,
                  onPressed: () {
                    linIndex--;
                    indexOfMedicationClassList = 0;
                    model.notifyListeners();
                  },
                ),
              ),
              SizedBox(width: 20.w),
              Flexible(
                child: ButtonWidget(
                  border: 100.r,
                  fontSize: 14.sp,
                  buttonColor: AppColors.primary,
                  isLoading: model.isLoading,
                  buttonText: phoneReminderList.isEmpty
                      ? 'Set Up'
                      : 'Proceed to Pay',
                  color: AppColors.white,
                  buttonBorderColor: AppColors.transparent,
                  onPressed: () {
                    if (phoneReminderList.isNotEmpty) {
                      if (phoneReminderList.contains(
                        SharedPreferencesService
                            .instance
                            .usersData['user']['phone'],
                      )) {
                      } else {
                        phoneReminderList.add(
                          SharedPreferencesService
                              .instance
                              .usersData['user']['phone'],
                        );
                      }
                      model.createReminderPaid(
                        context,
                        createReminderEntityModel: CreateReminderEntityModel(
                          medications: model.medicationClassList.map((m) {
                            return Medication(
                              medicationName: m.medicationName,
                              scheduleType: m.isCusSchedule!
                                  ? 'CUSTOM'
                                  : 'FIXED',
                              dosage: m.dosage,
                              medicationType: m.medicationType!.toUpperCase(),
                              startDateTime: m.startDateIso,
                              endDateTime: m.endDateIso,
                              durationInDays: int.parse(m.duration!),
                              timesPerDay: m.isCusSchedule!
                                  ? ''
                                  : int.parse(m.timesToTake!),
                              dailyDoseTimes: (m.dosageMap as List)
                                  .map(
                                    (dayData) => (dayData['doses'] as List)
                                        .map(
                                          (dose) => DailyDoseTime.fromJson(
                                            dose as Map<String, dynamic>,
                                          ),
                                        )
                                        .toList(),
                                  )
                                  .toList(),
                              note: m.note,
                              medicationImage: m.imageData!.url == null
                                  ? null
                                  : MedicationImage.fromJson(
                                      m.imageData!.toJson(),
                                    ),
                            );
                          }).toList(),
                          timeZone: "Africa/Lagos",
                          notificationChannels: notificationChannel,
                          emails: addedEmailReminderList,
                          phoneNumbers: addedPhoneReminderList,
                          payment: Payment(amount: costTotal, currency: "NGN"),
                        ),
                      );
                      model.notifyListeners();
                    } else {
                      model.createReminder(
                        context,
                        createReminderEntityModel: CreateReminderEntityModel(
                          medications: model.medicationClassList.map((m) {
                            return Medication(
                              medicationName: m.medicationName,
                              scheduleType: m.isCusSchedule!
                                  ? 'CUSTOM'
                                  : 'FIXED',
                              dosage: m.dosage,
                              medicationType: m.medicationType!.toUpperCase(),
                              startDateTime: m.startDateIso,
                              endDateTime: m.endDateIso,
                              durationInDays: int.parse(m.duration!),
                              timesPerDay: m.isCusSchedule!
                                  ? ''
                                  : int.parse(m.timesToTake!),
                              dailyDoseTimes: (m.dosageMap as List)
                                  .map(
                                    (dayData) => (dayData['doses'] as List)
                                        .map(
                                          (dose) => DailyDoseTime.fromJson(
                                            dose as Map<String, dynamic>,
                                          ),
                                        )
                                        .toList(),
                                  )
                                  .toList(),
                              note: m.note,
                              medicationImage: m.imageData!.url == null
                                  ? null
                                  : MedicationImage.fromJson(
                                      m.imageData!.toJson(),
                                    ),
                            );
                          }).toList(),
                          timeZone: "Africa/Lagos",
                          notificationChannels: notificationChannel,
                          emails: addedEmailReminderList,
                        ),
                      );
                    }
                    model.notifyListeners();
                  },
                ),
              ),
            ],
          ),
          SizedBox(height: 26.h),
        ],
      ),
    ),
  );

