  String showNoTimes(number) {
    if (number == 1) {
      return 'Once Daily';
    } else if (number == 2) {
      return 'Twice Daily';
    } else if (number == 3) {
      return 'Thrice Daily';
    } else if (number == 4) {
      return 'Four Daily';
    }
    return 'Five Daily';
  }

  String showNoTimesMode(int number) {
    if (number == 1) {
      return 'Once Daily';
    } else if (number == 2) {
      return 'Twice Daily';
    } else if (number == 3) {
      return 'Thrice Daily';
    } else if (number == 4) {
      return 'Four Times Daily';
    }
    return 'Custom Schedule';
  }

  returnChannelIconHeight(text) {
    if (text == 'SMS (₦150.00)') {
      return 24.0.h;
    }
    if (text == 'Email (Free)') {
      return 13.8.h;
    }
    return 17.8.h;
  }

  returnChannelIconWidth(text) {
    if (text == 'SMS (₦150.00)') {
      return 24.0.w;
    }
    if (text == 'Email (Free)') {
      return 10.8.w;
    }
    return 18.w;
  }

